import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"73. 断言和防御性编程","description":"The Little Book of C 中文版 — 73. 断言和防御性编程","frontmatter":{"title":"73. 断言和防御性编程","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","08-调试测试与 profiling","中文"],"description":"The Little Book of C 中文版 — 73. 断言和防御性编程","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":73,"sidebarWeight":73,"alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/073-Assertions and Defensive Programming","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/073-Assertions and Defensive Programming"},"headers":[],"relativePath":"posts/c教程/zh-CN/08-调试测试与 profiling/073-Assertions and Defensive Programming.md","filePath":"posts/c教程/zh-CN/08-调试测试与 profiling/073-Assertions and Defensive Programming.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/08-调试测试与 profiling/073-Assertions and Defensive Programming.md"};function t(l,a,o,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/08-Debugging Testing Profiling/073-Assertions and Defensive Programming)</p><p>错误是不可避免的，但崩溃不一定是这样。 C 为您提供了对机器的直接控制权，这意味着您必须保护自己的假设。这就是断言和防御性编程的用武之地：它们可以帮助您尽早发现错误，快速失败，并使您的代码可预测。</p><h4 id="步骤-1-什么是断言" tabindex="-1">步骤 1. 什么是断言？ <a class="header-anchor" href="#步骤-1-什么是断言" aria-label="Permalink to &quot;步骤 1. 什么是断言？&quot;">​</a></h4><p>断言是代码中内置的健全性检查。它测试你相信的事情是否真实。如果没有，程序会立即停止并显示错误消息，以免事情变得更糟。</p><p>包含标题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span></code></pre></div><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int divide(int a, int b) {</span></span>
<span class="line"><span>    assert(b != 0);  // ensure no division by zero</span></span>
<span class="line"><span>    return a / b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果<code>b</code>为零，程序中止：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assertion failed: (b != 0), function divide, file main.c, line 3.</span></span></code></pre></div><h4 id="步骤-2-断言如何工作" tabindex="-1">步骤 2. 断言如何工作 <a class="header-anchor" href="#步骤-2-断言如何工作" aria-label="Permalink to &quot;步骤 2. 断言如何工作&quot;">​</a></h4><p><code>assert(expression)</code>扩展到类似：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (!(expression)) {</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Assertion failed: %s, file %s, line %d\\n&quot;,</span></span>
<span class="line"><span>            &quot;expression&quot;, __FILE__, __LINE__);</span></span>
<span class="line"><span>    abort();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>正常编译时，它会检查条件。当编译时<code>-DNDEBUG</code>，断言被禁用。</p><h4 id="步骤-3-启用或禁用断言" tabindex="-1">步骤 3. 启用或禁用断言 <a class="header-anchor" href="#步骤-3-启用或禁用断言" aria-label="Permalink to &quot;步骤 3. 启用或禁用断言&quot;">​</a></h4><p>默认值：断言处于活动状态。要禁用它们（对于生产版本）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DNDEBUG program.c -o program</span></span></code></pre></div><p>在那个建筑中，<code>assert()</code>语句被删除。</p><p>这使您可以保留调试检查，而不会减慢发布二进制文件的速度。</p><h4 id="步骤-4-实际示例" tabindex="-1">步骤 4. 实际示例 <a class="header-anchor" href="#步骤-4-实际示例" aria-label="Permalink to &quot;步骤 4. 实际示例&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int find_max(int *arr, int n) {</span></span>
<span class="line"><span>    assert(arr != NULL);</span></span>
<span class="line"><span>    assert(n &gt; 0);</span></span>
<span class="line"><span>    int max = arr[0];</span></span>
<span class="line"><span>    for (int i = 1; i &lt; n; i++)</span></span>
<span class="line"><span>        if (arr[i] &gt; max) max = arr[i];</span></span>
<span class="line"><span>    return max;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int data[] = {3, 5, 7, 2, 8};</span></span>
<span class="line"><span>    printf(&quot;Max: %d\\n&quot;, find_max(data, 5));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果你通过了<code>NULL</code>指针或无效长度，程序立即失败。</p><h4 id="第-5-步-编写好的断言" tabindex="-1">第 5 步：编写好的断言 <a class="header-anchor" href="#第-5-步-编写好的断言" aria-label="Permalink to &quot;第 5 步：编写好的断言&quot;">​</a></h4><p>断言应该测试内部假设，而不是用户输入。坏的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert(argc == 3);</span></span></code></pre></div><p>好的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (argc != 3) {</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Usage: %s input output\\n&quot;, argv[0]);</span></span>
<span class="line"><span>    return 1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用断言来检查逻辑中的不变量，除非存在错误，否则永远不应该发生的事情。</p><h4 id="步骤-6-防御性编程技术" tabindex="-1">步骤 6. 防御性编程技术 <a class="header-anchor" href="#步骤-6-防御性编程技术" aria-label="Permalink to &quot;步骤 6. 防御性编程技术&quot;">​</a></h4><p>防御性编程超越了断言，它是编写假设错误会发生的代码。</p><p>检查每个函数的返回值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *f = fopen(&quot;file.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>if (!f) {</span></span>
<span class="line"><span>    perror(&quot;fopen&quot;);</span></span>
<span class="line"><span>    return 1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>验证输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int divide(int a, int b) {</span></span>
<span class="line"><span>    if (b == 0) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Division by zero!\\n&quot;);</span></span>
<span class="line"><span>        return 0;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return a / b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>避免未定义的行为：</p><ul><li>初始化所有变量。</li><li>不要访问已释放的内存。</li><li>检查数组边界。</li><li>始终匹配<code>malloc()</code>和<code>free()</code>.</li></ul><h4 id="步骤-7-复杂系统中的断言" tabindex="-1">步骤 7. 复杂系统中的断言 <a class="header-anchor" href="#步骤-7-复杂系统中的断言" aria-label="Permalink to &quot;步骤 7. 复杂系统中的断言&quot;">​</a></h4><p>在大型程序中，断言就像绊线一样，用于检测状态何时变得不一致。</p><p>示例：队列</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>void enqueue(int *queue, int *count, int value, int max) {</span></span>
<span class="line"><span>    assert(*count &lt; max);</span></span>
<span class="line"><span>    queue[*count] = value;</span></span>
<span class="line"><span>    (*count)++;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果您的逻辑出现问题，断言会在内存损坏发生之前立即告诉您。</p><h4 id="步骤-8-日志记录与断言" tabindex="-1">步骤 8. 日志记录与断言 <a class="header-anchor" href="#步骤-8-日志记录与断言" aria-label="Permalink to &quot;步骤 8. 日志记录与断言&quot;">​</a></h4><ul><li>断言：捕获编程错误。</li><li>日志记录：记录运行时信息。</li></ul><p>结合两者：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int read_value(int *arr, int n, int index) {</span></span>
<span class="line"><span>    assert(index &gt;= 0 &amp;&amp; index &lt; n);</span></span>
<span class="line"><span>    printf(&quot;Reading arr[%d] = %d\\n&quot;, index, arr[index]);</span></span>
<span class="line"><span>    return arr[index];</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="步骤-9-使用-static-assert-进行编译时检查-c11" tabindex="-1">步骤 9. 使用 static_assert 进行编译时检查 (C11+) <a class="header-anchor" href="#步骤-9-使用-static-assert-进行编译时检查-c11" aria-label="Permalink to &quot;步骤 9. 使用 static_assert 进行编译时检查 (C11+)&quot;">​</a></h4><p>C11介绍<code>_Static_assert</code>，它在编译期间检查条件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>_Static_assert(sizeof(int) == 4, &quot;int must be 4 bytes&quot;);</span></span></code></pre></div><p>如果条件失败，编译器将停止并显示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: static assertion failed: &quot;int must be 4 bytes&quot;</span></span></code></pre></div><p>这非常适合配置或架构假设。</p><h4 id="步骤-10-小代码-安全数组访问" tabindex="-1">步骤 10. 小代码：安全数组访问 <a class="header-anchor" href="#步骤-10-小代码-安全数组访问" aria-label="Permalink to &quot;步骤 10. 小代码：安全数组访问&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define MAX 5</span></span>
<span class="line"><span>int safe_get(int arr[], int n, int i) {</span></span>
<span class="line"><span>    assert(i &gt;= 0 &amp;&amp; i &lt; n);</span></span>
<span class="line"><span>    return arr[i];</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int nums[MAX] = {1, 2, 3, 4, 5};</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, safe_get(nums, MAX, 2));  // OK</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, safe_get(nums, MAX, 10)); // triggers assertion</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assertion failed: (i &gt;= 0 &amp;&amp; i &lt; n), function safe_get, file main.c, line 7.</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>断言和防御性编码使您的软件：</p><ul><li>更安全，尽早发现错误。</li><li>更容易调试，从源头失败，而不是以后失败。</li><li>更易于维护，清楚地记录假设。</li></ul><p>在 C 语言中，一个错误的指针可能会导致系统崩溃。断言是你的安全网。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>将断言添加到堆栈或链表实现中。</li><li>编写一个函数，在继续操作之前验证所有参数。</li><li>使用<code>_Static_assert</code>检查跨平台程序中的类型大小。</li><li>将断言与日志记录结合起来以获得详细的错误报告。</li><li>使用无效输入运行程序，看看断言检测问题的速度有多快。</li></ol><p>接下来，您将进入 C 语言单元测试，构建小型自动化测试，以确保每个功能完全按预期工作。</p>`,62)])])}const g=s(i,[["render",t]]);export{u as __pageData,g as default};
